function table(headers,rows,empty='No records match your selection.'){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.map(row=>'<tr>'+row.map(cell=>'<td>'+cell+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+headers.length+'"><div class="empty"><strong>No records to display</strong>'+empty+'</div></td></tr>')+'</tbody></table></div>'}
function paged(key,headers,rows,empty){const size=state.sizes[key]||25,max=Math.max(1,Math.ceil(rows.length/size));state.pages[key]=Math.max(1,Math.min(max,state.pages[key]||1));const page=state.pages[key],start=(page-1)*size;return table(headers,rows.slice(start,start+size),empty)+'<div class="pagination"><span>Showing '+(rows.length?start+1:0)+'–'+Math.min(start+size,rows.length)+' of '+rows.length+'</span><div class="toolbar"><select data-size="'+key+'" aria-label="Rows per page">'+options([25,50,100],size)+'</select>'+button('←','page','data-key="'+key+'" data-delta="-1" '+(page===1?'disabled':''))+'<span>'+page+' / '+max+'</span>'+button('→','page','data-key="'+key+'" data-delta="1" '+(page===max?'disabled':''))+'</div></div>'}
