function renderReports(){const head=heading('ATTENDANCE INTELLIGENCE','Attendance reports','Check-in, check-out, late arrivals and exceptions.',button('Print / PDF','report-print','','ghost')+button('Export Excel','report-export','',''));let data;try{data=getReport()}catch(e){return head+'<section class="panel">'+reportControls()+'<div class="panel-content"><p class="notice error">'+E(e.message)+'</p></div></section>'}const present=data.rows.filter(r=>r.status==='Present').length;return head+'<section class="panel"><div class="panel-heading"><div><h2>'+displayDate(data.from)+(data.from!==data.to?' — '+displayDate(data.to):'')+'</h2><small>Asia/Dhaka · Work duration is the first-in to last-out span less configured break.</small></div>'+tag(state.reportView==='summary'?'Employee summary':'Daily detail','neutral')+'</div>'+reportControls()+'<div class="summary-line"><span>Present <b>'+present+'</b></span><span>Absent <b>'+data.rows.filter(r=>r.status==='Absent').length+'</b></span><span>Late arrivals <b>'+data.rows.filter(r=>r.lateMinutes).length+'</b></span><span>Early departures <b>'+data.rows.filter(r=>r.earlyMinutes).length+'</b></span><span>Missing punches <b>'+data.rows.filter(r=>r.missingIn||r.missingOut).length+'</b></span></div>'+paged('reports',state.reportView==='summary'?reportSummaryHeaders:attendanceHeaders,state.reportView==='summary'?data.summary.map(summaryCells):data.rows.map(attendanceCells))+'</section>'}
