function renderSettings(){const r=rules();return heading('WORKSPACE PREFERENCES','Attendance settings','Shift rules, receiver address and company holidays.')+'<section class="panel"><div class="panel-heading"><h2>Shift & connection settings</h2>'+tag('Asia/Dhaka','neutral')+'</div><div class="panel-content"><form class="form-grid" data-form="settings">'+formHeading('Working schedule')+input('Shift start','start',r.start,'time',true)+input('Shift end','end',r.end,'time',true)+input('Arrival grace (minutes)','grace',r.grace,'number',true)+input('Unpaid break (minutes)','breakMinutes',r.breakMinutes,'number',true)+select('Weekly off day','off',['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((v,i)=>[i,v]),r.off)+input('Device offline after (seconds)','heartbeatSeconds',r.heartbeatSeconds,'number',true)+formHeading('Device server')+input('ADMS receiver hostname','receiverHost',r.receiverHost||'','text',false,'Hostname only; use the device receiver, not the login service.')+'<div class="wide hint">Grace applies to late-arrival classification. After grace, lateness is counted from shift start. This workspace supports same-day shifts.</div>'+actions('Save settings')+'</form></div></section><section class="panel"><div class="panel-heading"><h2>Company holidays</h2>'+button('+ Add holiday','holiday-new')+'</div>'+table(['Date','Holiday'],records('holiday').sort((a,b)=>a.date.localeCompare(b.date)).map(h=>[displayDate(h.date),E(h.name)]),'No company holidays added.')+'</section>'}
function render(){if(!state.received||state.closed)return;try{$('navigation').innerHTML=menus.map(([id,label])=>'<button type="button" data-nav="'+id+'" class="'+(state.page===id?'active':'')+'">'+icon(id)+'<span>'+label+'</span></button>').join('');$('breadcrumb').textContent=menus.find(m=>m[0]===state.page)?.[1]||'Attendance';const pages={dashboard:renderDashboard,employees:renderEmployees,reports:renderReports,leave:renderLeave,devices:renderDevices,activity:renderActivity,settings:renderSettings};$('app').innerHTML=pages[state.page]();state.dirty=false;window.attendanceBoot.phase('ready');updateStatus();}catch(e){window.attendanceBoot.fail('Some attendance records could not be displayed. Please try again.');console.error('Attendance render failed',e?.message)}}
function canDraw(){return !$('dialog').open&&!document.activeElement?.matches?.('input,select,textarea')}
function scheduleRender(){state.dirty=true;clearTimeout(renderTimer);renderTimer=setTimeout(()=>{if(canDraw())render()},120)}
function updateStatus(){const c=$('connection');c.className='connection '+(state.connected&&state.received?'live':'offline');c.replaceChildren();const dot=document.createElement('i');c.append(dot,document.createTextNode(state.connected&&state.received?'Live · '+(state.updatedAt?stamp(state.updatedAt):'Connected'):state.received?'Reconnecting':'Connecting'));$('clock').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Dhaka',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());$('admin-avatar').textContent=(state.identity?.role||'Admin').slice(0,1)}
function notify(message,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.textContent=message;$('toasts').append(n);setTimeout(()=>n.remove(),6000)}
function openDialog(title,body,eyebrow='WORKFORCE MANAGEMENT'){clearTimeout(renderTimer);$('dialog-title').textContent=title;$('dialog-eyebrow').textContent=eyebrow;$('dialog-body').innerHTML=body;$('dialog-error').textContent='';$('dialog').showModal()}
function closeDialog(){const d=$('dialog');if(d.open)d.close();if(state.dirty)scheduleRender()}
function employeeDialog(id,prefill={}){const e=employees().find(v=>v.id===id)||prefill;openDialog(e.id?'Edit employee':'Add employee','<form data-form="employee" data-id="'+E(e.id||'')+'" class="form-grid">'+formHeading('Employee information')+input('Employee ID','employeeId',e.employeeId||'','text',true)+input('Full name','name',e.name||'','text',true)+branchInput(e.branch||'')+input('Joining date','join',e.join||C.today(),'date',true)+input('Department','department',e.department||'')+input('Designation','designation',e.designation||'')+select('Attendance access','allBranchAttendance',[[false,'Home branch only'],[true,'All branches — consolidate profiles (DM only)']],e.allBranchAttendance===true)+ '<p class="notice wide">For DM access, use designation DM and the same unique user ID on every device. Saving All branches combines profiles with the same name and user ID, including saved attendance. Face/fingerprint must be enrolled on each machine.</p>'+formHeading('Contact information')+input('Employee mobile','employeeNumber',e.employeeNumber||'','tel')+input('Personal mobile','personalNumber',e.personalNumber||'','tel')+input('Email','email',e.email||'','email')+input('Emergency contact','emergencyContact',e.emergencyContact||'','tel')+input('Address','address',e.address||'')+select('Status','active',[[true,'Active'],[false,'Inactive']],e.active!==false)+input('Inactive from','inactiveFrom',e.inactiveFrom||C.today(),'date')+formHeading('Machine mapping')+input('Device user ID','code',e.code||'','text',true,'Must match the employee’s ID on the machine.')+input('Device display name (optional)','deviceName',e.deviceName||'','text',false,'Use a short name supported by your machine.')+actions(e.id?'Save changes':'Save employee')+'</form>')}
function deviceImportDialog(deviceId){
 const available=devices();
 if(!available.length){notify('Add a device in Devices before importing users.',true);return;}
 const selected=available.find(d=>d.id===deviceId)||available[0];
 openDialog('Import device users','<form data-form="device-employees" class="form-grid">'+select('Device','device',available.map(d=>[d.id,d.name+' · '+(d.location||'No branch')]),selected.id)+branchInput(selected.location||'')+input('Joining date for this batch','join','','date',true,'Enter the joining date for these employees. Correct individual dates in Edit after import if needed.')+'<div class="wide hint">Import all unmapped downloaded users as employees. Employee ID uses the machine user ID. Existing employees and their profile details remain unchanged. Review contact details after import.</div><div class="wide" id="device-import-preview"></div>'+actions('Import users to Employees')+'</form>','EMPLOYEE IMPORT');
 updateDeviceImportPreview();
}
function updateDeviceImportPreview(){
 const f=$('dialog-body').querySelector('[data-form="device-employees"]');if(!f)return;
 const users=records('deviceUser').filter(u=>u.device===f.elements.device.value),mapped=users.filter(u=>employees().some(e=>C.deviceEmployeeMatches(e,devices().find(d=>d.id===f.elements.device.value)||{},u.code)));
 const device=devices().find(d=>d.id===f.elements.device.value),submit=f.querySelector('button[type=submit]');if(submit)submit.disabled=!users.length;
 if(!users.length){const ready=device&&C.connectionState(device,state.records).supportsPush;$('device-import-preview').innerHTML='<div class="notice">No users downloaded from '+E(device?.name||'this device')+' yet. '+(ready?'Use Read device users, then reopen this import window.':'Open device Setup to check the connection. Online receiver v2 with user commands is required for ADMS downloads.')+'</div>'+button('Open device setup','device-setup','data-id="'+E(device?.id||'')+'"')+(ready?button('Read device users','device-users','data-id="'+E(device.id)+'"'):'');return;}
 $('device-import-preview').innerHTML='<p>'+users.length+' downloaded · '+(users.length-mapped.length)+' new · '+mapped.length+' already registered</p>'+table(['Device user ID','Name','Import status'],users.map(u=>[E(u.code),E(u.name||'Missing name'),mapped.includes(u)?tag('Already registered','neutral'):tag('New employee','blue')]));
}
async function importDeviceEmployees(data){
 const plan=C.deviceEmployeeImport(state.records,data.device,data.join,data.branch);
 const updatedAt=new Date().toISOString();for(const value of Object.values(plan.updates)){value.updatedAt=updatedAt;value.importedBy=auth.currentUser.uid;}
 const added=Object.keys(plan.updates).length;if(added)await commit(plan.updates);
 return {added,skipped:plan.skipped.length};
}
function receiverConfigureDialog(){
 openDialog('Configure ADMS receiver','<form data-form="receiver" class="form-grid">'+input('ADMS receiver address','receiverHost',rules().receiverHost||'','text',true,'Enter the hostname or paste the HTTPS home address.')+'<div class="wide hint">This saves the server address only. Shift and attendance settings stay unchanged.</div>'+actions('Save receiver')+'</form>','DEVICE CONNECTION');
}
async function saveReceiver(input){
 const host=C.normalizeReceiverHost(input.receiverHost),updatedAt=new Date().toISOString();
 await commit({'settings/receiverHost':host,'settings/kind':'settings','settings/updatedAt':updatedAt});
 const existing=state.records.find(r=>r.id==='settings');
 if(existing)Object.assign(existing,{receiverHost:host,kind:'settings',updatedAt});
 else state.records.push({id:'settings',kind:'settings',receiverHost:host,updatedAt});
 return host;
}
function deviceDialog(id){const d=devices().find(v=>v.id===id)||{};openDialog(d.id?'Edit device':'Add device','<form data-form="device" data-id="'+E(d.id||'')+'" class="form-grid">'+input('Device name','name',d.name||'','text',true)+input('Branch / location','location',d.location||'','text',true)+select('Model','model',['ZKTeco MB20-VL','ZKTeco K60','ZKTeco MB20','Other'],d.model||'ZKTeco MB20-VL')+select('Connection type','accessType',[['ADMS','ADMS / Cloud'],['Device','Local TCP/IP connector']],d.accessType||'ADMS')+'<div class="form-grid wide" id="adms-fields">'+input('Device serial number','serial',d.serial||'','text',true)+input('Branch Internet public IP','publicIp',d.publicIp||'','text',!d.id,'The router’s Internet IP, not the machine’s local IP.')+'</div><div class="form-grid wide" id="local-fields" hidden>'+input('Device local IP','address',d.address||'','text',false)+input('TCP port','port',d.port||4370,'number',false)+'</div><details class="advanced"><summary>Advanced settings</summary><div class="form-grid">'+input('Receiver hostname','serverHost',d.serverHost||rules().receiverHost||'')+select('Server protocol','transport',['HTTPS','HTTP'],d.transport||'HTTPS')+input('Server port','serverPort',d.serverPort||(d.transport==='HTTP'?80:443),'number')+select('Device status','active',[[true,'Active'],[false,'Inactive']],d.active!==false)+'</div></details>'+actions('Save device')+'</form>','ZKTECO DEVICE');updateDeviceFields()}
function updateDeviceFields(){const f=$('dialog-body').querySelector('[data-form=device]');if(!f)return;const adms=f.elements.accessType.value==='ADMS';for(const [id,visible]of [['adms-fields',adms],['local-fields',!adms]]){$(id).hidden=!visible;$(id).querySelectorAll('input').forEach(n=>n.disabled=!visible)}f.elements.address.required=!adms;f.elements.port.required=!adms;f.elements.serial.required=adms;f.elements.publicIp.required=adms&&!devices().some(d=>d.id===f.dataset.id)}
function setupDialog(id){const d=devices().find(d=>d.id===id);if(!d)return;const adms=d.accessType==='ADMS',host=d.serverHost||rules().receiverHost||'',values=adms?[['Server address',host||'Not configured'],['Port',d.serverPort||(d.transport==='HTTP'?80:443)],['HTTPS',d.transport==='HTTP'?'Off':'On'],['Domain name','On'],['Serial number',d.serial],['Time zone','UTC+06:00']]:[['Connection','Local connector'],['Device ID',d.id],['Local IP',d.address],['Port',d.port||4370]];openDialog(d.name+' · Setup','<div class="setup-values">'+values.map(([k,v])=>'<div><small>'+E(k)+'</small>'+E(v)+'</div>').join('')+'</div><ol class="setup-steps">'+(adms?'<li>Connect the machine to Internet through Ethernet or Wi-Fi.</li><li>Open COMM → Cloud Server / ADMS settings. Enter the server address and port shown above. Do not include https:// or a path in the address.</li><li>The device firmware must support the selected HTTP/HTTPS protocol. Use the local connector if ADMS is unavailable.</li><li>Match the registered serial number and branch public IP. The first accepted heartbeat changes the status to Online.</li>':'<li>Run the local connector on a computer connected to the same LAN as the device.</li><li>Use the device ID, local IP and port shown above. Configure the machine communication key privately on that computer.</li><li>Keep the connector computer and its Internet connection running.</li>')+'<li>Match each employee’s device user ID, then record a test punch.</li></ol><div class="toolbar">'+button('Copy settings','copy-setup','data-id="'+E(id)+'"','','')+button('Import to Employees','employee-import-device','data-id="'+E(id)+'"')+button('Read device users','device-users','data-id="'+E(id)+'" '+(!C.connectionState(d,state.records).supportsPush?'disabled':''))+(adms?'':button('Connector config','connector-config','data-id="'+E(id)+'"'))+'</div>'+(records('deviceUser').some(u=>u.device===id)?'<div class="subtle-divider"></div><h3>Device users</h3>'+table(['User ID','Device name','Employee mapping'],records('deviceUser').filter(u=>u.device===id).slice(0,50).map(u=>['<span class="mono">'+E(u.code)+'</span>',E(u.name),employees().some(e=>C.deviceEmployeeMatches(e,d,u.code))?tag('Mapped'):button('Create employee','employee-from-device','data-id="'+E(u.id)+'"')])):'') ,'DEVICE CONNECTION')}
function manualDialog(){openDialog('Manual attendance','<form data-form="punch" class="form-grid">'+select('Employee','employee',employees().map(e=>[e.id,e.name]),'', 'Select employee')+input('Date','date',C.today(),'date',true)+input('Time','time',C.timeNow(),'time',true)+select('Punch type','direction',[['in','Check-in'],['out','Check-out']],'in')+actions('Save attendance')+'</form>')}
function leaveDialog(){openDialog('New leave request','<form data-form="leave" class="form-grid">'+select('Employee','employee',employees().map(e=>[e.id,e.name]),'','Select employee')+input('From','from',C.today(),'date',true)+input('To','to',C.today(),'date',true)+'<label class="wide">Reason<textarea name="reason" required maxlength="500"></textarea></label>'+actions('Submit request')+'</form>')}
function pushDialog(id){const d=devices().find(d=>d.id===id);if(!d)return;if(!C.connectionState(d,state.records,Date.now(),rules().heartbeatSeconds).supportsPush){notify('An online receiver v2 or local connector is required.',true);return}const candidates=employees().filter(e=>!e.deleted&&e.active!==false).sort((a,b)=>String(a.name).localeCompare(String(b.name)));openDialog('Push users · '+d.name,'<form data-form="push" data-device="'+E(d.id)+'"><p class="hint">Sends device user IDs and display names. Fingerprints and face templates remain on the machine.</p><div class="selection-tools"><span>Select employees</span><button type="button" class="secondary small" data-action="select-users">Select all</button></div><div class="check-list">'+candidates.map(e=>'<label><input type="checkbox" name="employees" value="'+E(e.id)+'"><span>'+E(e.name)+'</span><small>'+E(e.code)+' · '+E(e.branch)+'</small></label>').join('')+'</div>'+actions('Queue user push')+'</form>','DEVICE USER SYNC')}
async function commit(updates){if(!auth?.currentUser||state.closed)throw Error('Your session has ended. Reopen Attendance from DMS.');if(!state.connected||navigator.onLine===false)throw Error('You are offline. Reconnect before saving.');const gen=state.generation;const t=setTimeout(()=>notify('Awaiting server confirmation. Keep this form open; do not submit it again.'),12000);try{await sdk.update(sdk.ref(db,'attendance/records'),updates);if(gen!==state.generation||state.closed)throw Error('The session ended before confirmation. Reopen Attendance to verify.')}finally{clearTimeout(t)}}
async function saveRecord(kind,data,id){if(id&&/[.#$\[\]\/]/.test(id))throw Error('Invalid record ID.');let value={...data},merge={updates:{},ids:[]};if(kind==='employee'){const input={...employees().find(e=>e.id===id),...data};merge=C.prepareDmMerge(state.records,input,id);value=C.validateEmployee(input,employees().filter(e=>!merge.ids.includes(e.id)),id);}else if(kind==='device')value=C.validateDevice(data,devices(),id);else if(kind==='settings')value=C.validateRules(data);else if(kind==='punch'){if(!employees().some(e=>e.id===data.employee)||!C.validDate(data.date)||!C.validTime(data.time)||!['in','out'].includes(data.direction))throw Error('Select a valid employee, date, time and punch type.');if(records('punch').some(p=>p.employee===data.employee&&p.date===data.date&&p.time===data.time&&C.punchDirection(p)===data.direction))throw Error('This attendance punch already exists.');value.source='Manual';}else if(kind==='leave'){if(!employees().some(e=>e.id===data.employee)||!C.validDate(data.from)||!C.validDate(data.to)||data.from>data.to||!data.reason)throw Error('Select a valid employee, leave dates and reason.');if(!id)value.status='Pending';}else if(kind==='holiday'){if(!C.validDate(data.date)||!data.name?.trim())throw Error('Enter a holiday name and valid date.');}else throw Error('Unsupported record type.');const key=kind==='settings'?'settings':kind==='holiday'?'holiday_'+data.date:kind==='punch'?'p_'+data.employee+'_'+data.date+'_'+data.time.replaceAll(':','')+'_'+data.direction:id||crypto.randomUUID();value={...(id?state.records.find(r=>r.id===id):{}),...value,kind,updatedAt:new Date().toISOString()};delete value.id;await commit({...merge.updates,[key]:value});return key;}
async function queueOperation(device,action,employeeIds=[]){const d=devices().find(v=>v.id===device),connection=d&&C.connectionState(d,state.records,Date.now(),rules().heartbeatSeconds);if(!d||!connection.online||Number(connection.status.protocolVersion)<2)throw Error('Connect the upgraded device receiver first.');if(!['upsert_user','pull_attendance','inspect_users'].includes(action))throw Error('Unsupported device operation.');if(action==='upsert_user'&&!connection.supportsPush)throw Error('User push is not supported by this connection.');const updates={},created=new Date().toISOString();if(action==='upsert_user'){if(!employeeIds.length||employeeIds.length>100)throw Error('Select between 1 and 100 employees per batch.');for(const id of new Set(employeeIds)){const e=employees().find(e=>e.id===id);if(!e||e.deleted||!C.safeDeviceCode(e.code))throw Error('An employee has an invalid device user ID.');if(state.records.some(j=>j.kind==='pushjob'&&j.device===device&&j.employee===id&&['Queued','Sent'].includes(j.status)))throw Error(e.name+' already has a pending push.');updates[crypto.randomUUID()]={kind:'pushjob',action,device,employee:id,code:String(e.code),name:e.deviceName||e.name,status:'Queued',created,requestedBy:auth.currentUser.uid};}}else{if(state.records.some(j=>j.kind==='syncjob'&&j.device===device&&j.action===action&&['Queued','Sent'].includes(j.status)))throw Error('This device already has a pending request.');updates[crypto.randomUUID()]={kind:'syncjob',action,device,status:'Queued',created,requestedBy:auth.currentUser.uid};}await commit(updates);}
function download(name,content,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function reportExportData(data=getReport()){
 const summary=state.reportView==='summary';
 return {headers:summary?['Employee ID','Name','Designation','Branch','Working days','Present','Absent','Leave','Late days','Early out days','Missing punches','Work minutes','Late minutes','Late checkout minutes']:['Date','Employee ID','Name','Designation','Branch','Attendance device / branch','Device user ID','Check-in','Check-out','Work minutes','Status','Late minutes','Early checkout minutes','Late checkout minutes','Missing in','Missing out'],
 rows:summary?data.summary.map(r=>[r.employeeId,r.name,r.designation||'—',r.branch,r.workingDays,r.present,r.absent,r.leave,r.late,r.early,r.missing,r.workMinutes,r.lateMinutes,r.overtimeMinutes]):data.rows.map(r=>[r.date,r.employeeId,r.name,r.designation||'—',r.branch,attendedDevices(r),r.code,r.first||'—',r.last||'—',r.workMinutes,r.status,r.lateMinutes,r.earlyMinutes,r.overtimeMinutes,r.missingIn?'Yes':'No',r.missingOut?'Yes':'No']),
 tones:summary?data.summary.map(r=>r.absent?'red':r.late||r.early||r.missing?'amber':'green'):data.rows.map(r=>r.status==='Absent'?'red':r.lateMinutes||r.earlyMinutes||r.missingIn||r.missingOut?'amber':r.status==='Present'?'green':r.status==='Leave'?'blue':'neutral')};
}
function exportReport(){const data=getReport(),out=reportExportData(data);download('attendance-'+data.from+'-'+data.to+'.xlsx',workbook({title:'M/S. Mostafa · Attendance report',subtitle:data.from+' — '+data.to+' | '+(state.reportView==='summary'?'Employee summary':'Daily detail')+' | Asia/Dhaka',...out}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');notify('All '+out.rows.length+' filtered rows exported to Excel.');}
function exportEmployees(){const list=employees().filter(e=>!e.deleted);download('employees.xlsx',workbook({title:'M/S. Mostafa · Employee directory',subtitle:'Generated '+C.today()+' | '+list.length+' employees',headers:['Employee ID','Name','Designation','Branch','Department','Joining date','Device user ID','Employee mobile','Personal mobile','Email','Status'],rows:list.map(e=>[e.employeeId,e.name,e.designation||'—',e.branch,e.department,e.join,e.code,e.employeeNumber,e.personalNumber,e.email,e.active===false?'Inactive':'Active']),tones:list.map(e=>e.active===false?'neutral':'green')}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');notify('Employee directory exported to Excel.');}
function printReport(){const data=getReport(),summary=state.reportView==='summary',present=data.rows.filter(r=>r.status==='Present').length,absent=data.rows.filter(r=>r.status==='Absent').length,late=data.rows.filter(r=>r.lateMinutes).length;const content=table(summary?reportSummaryHeaders:attendanceHeaders,summary?data.summary.map(summaryCells):data.rows.map(attendanceCells));$('print-area').innerHTML='<header class="print-heading"><div><span class="print-brand">M/S. MOSTAFA</span><h1>Attendance report</h1><p>'+displayDate(data.from)+(data.from!==data.to?' — '+displayDate(data.to):'')+' · '+(summary?'Employee summary':'Daily detail')+'</p></div><div class="print-meta">DMS Workforce<br>Generated '+E(stamp(new Date()))+'<br>Asia/Dhaka</div></header><div class="print-summary"><span>Employees <b>'+new Set(data.rows.map(r=>r.employee)).size+'</b></span><span>Present <b>'+present+'</b></span><span>Absent <b>'+absent+'</b></span><span>Late <b>'+late+'</b></span><span>Rows <b>'+ (summary?data.summary.length:data.rows.length)+'</b></span></div><p class="print-filter">'+E([state.reportBranch||'All branches',state.reportEmployee?employees().find(e=>e.id===state.reportEmployee)?.name:'All employees',state.reportStatus||'All statuses',state.reportSearch?'Search: '+state.reportSearch:''].filter(Boolean).join(' · '))+'</p>'+content+'<div class="print-signatures"><span>Prepared by</span><span>Checked by</span><span>Approved by</span></div><footer class="print-footer">Copyright © 2026 Zahangir Kabir. All rights reserved.</footer>';window.print();}
function employeeDevice(e){const exact=devices().find(d=>d.id===e.sourceDevice);if(exact)return exact;const matches=devices().filter(d=>String(d.location||'').trim().toLowerCase()===String(e.branch||'').trim().toLowerCase());return matches.length===1?matches[0]:null;}
function duplicateSadarEmployees(){const normalize=v=>String(v||'').toLowerCase().replace(/[^a-z0-9]/g,'');return employees().filter(e=>!e.deleted&&/sadar|manikganj/i.test(e.branch||'')&&employees().some(other=>!other.deleted&&other.id!==e.id&&/^singair$/i.test(other.branch||'')&&String(e.code)===String(other.code)&&normalize(e.name)&&normalize(e.name)===normalize(other.name)));}
function deleteEmployeesDialog(ids,cleanup=false){const selected=employees().filter(e=>ids.includes(e.id)&&!e.deleted);if(!selected.length)throw Error('Select employees first. No exact Sadar duplicates found if reviewing duplicates.');openDialog(cleanup?'Remove duplicate Sadar employees':'Remove selected employees','<form data-form="employees-delete"><input type="hidden" name="ids" value="'+E(selected.map(e=>e.id).join(','))+'"><p>Review '+selected.length+' employees before removing them.</p>'+table(['User ID','Name','Branch','Device'],selected.map(e=>[E(e.code),E(e.name),E(e.branch),E(employeeDevice(e)?.name||'Not mapped')]))+'<p class="notice">Device removal permanently deletes the enrolled user from the mapped machine. Re-enrollment may be required. Previous attendance remains in DMS. Offline devices process queued requests when they reconnect.</p><label class="delete-choice"><input type="checkbox" name="removeDevice" value="yes" checked> Permanently remove from the mapped device too</label>'+input('Type DELETE to confirm','confirmation','','text',true)+actions('Remove employees')+'</form>','CONFIRM DELETION');}
function deleteEmployeeDialog(id){return deleteEmployeesDialog([id]);}
async function removeEmployees(ids,removeDevice){if(!['Admin','DM'].includes(state.identity?.role))throw Error('An Admin or DM session is required.');const selected=employees().filter(e=>ids.includes(e.id)&&!e.deleted);if(!selected.length)throw Error('No employees selected.');const now=new Date().toISOString(),updates={};for(const e of selected){const fields=C.employeeDeletion(e,C.today(),now,auth.currentUser.uid);for(const [k,v]of Object.entries(fields))updates[e.id+'/'+k]=v;for(const j of records('pushjob').filter(j=>j.employee===e.id&&j.status==='Queued'&&j.action!=='delete_user')){updates[j.id+'/status']='Failed';updates[j.id+'/error']='Employee removed before delivery';updates[j.id+'/completedAt']=now;}if(removeDevice){const d=employeeDevice(e),st=d&&C.connectionState(d,state.records).status;if(!d)throw Error(e.name+': device mapping is missing.');if(!st?.capabilities?.includes('delete_user'))throw Error(d.name+': update the ADMS receiver or local connector for user deletion first.');if(!C.safeDeviceCode(e.code))throw Error('Invalid device user ID.');if(employees().some(other=>other.id!==e.id&&!other.deleted&&!ids.includes(other.id)&&String(other.code)===String(e.code)&&employeeDevice(other)?.id===d.id))throw Error(e.name+': another employee uses this ID on the same device.');updates[crypto.randomUUID()]={kind:'pushjob',action:'delete_user',device:d.id,employee:e.id,code:String(e.code),name:e.name,status:'Queued',created:now,requestedBy:auth.currentUser.uid};updates[e.id+'/deviceDeletionStatus']='Queued';}}
await commit(updates);state.employeeSelected=[];notify(removeDevice?'Employees removed. Device deletion queued; check Sync activity.':'Employees removed from DMS. Attendance history preserved.');}

async function deleteEmployee(id){if(!['Admin','DM'].includes(state.identity?.role))throw Error('An Admin or DM session is required.');const e=employees().find(e=>e.id===id&&!e.deleted);if(!e)throw Error('Employee has already been deleted.');const now=new Date().toISOString(),updates={};const fields=C.employeeDeletion(e,C.today(),now,auth.currentUser.uid);for(const [key,value]of Object.entries(fields))updates[id+'/'+key]=value;for(const job of state.records.filter(j=>j.kind==='pushjob'&&j.employee===id&&j.status==='Queued')){updates[job.id+'/status']='Failed';updates[job.id+'/error']='Employee deleted before delivery';updates[job.id+'/completedAt']=now;}await commit(updates);notify('Employee deleted. Previous attendance is preserved.');}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=ch}if(quoted)throw Error('Unclosed CSV quote.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows;}
async function importAttendance(file){if(!file||file.size>2*1024*1024)throw Error('Choose a CSV file smaller than 2 MB.');const rows=parseCsv((await file.text()).replace(/^\ufeff/,'')),header=rows.shift()?.map(v=>v.trim().toLowerCase());if(!header||header.slice(0,3).join(',')!=='user_id,date,time')throw Error('CSV columns must be user_id,date,time,direction (direction is optional).');if(rows.length>2000)throw Error('Import no more than 2,000 punches at once.');const updates={};let skipped=0;for(const [i,row]of rows.entries()){const [code,date,time,directionRaw]=row.map(v=>v.trim()),e=employees().find(e=>String(e.code)===code);if(!e||!C.validDate(date)||!C.validTime(time))throw Error('Row '+(i+2)+': employee mapping, date or time is invalid.');const direction=directionRaw?.toLowerCase();if(direction&&!['in','out'].includes(direction))throw Error('Row '+(i+2)+': direction must be in or out.');if(records('punch').some(p=>p.employee===e.id&&p.date===date&&p.time===time&&(C.punchDirection(p)||'')===(direction||''))){skipped++;continue}const key='p_'+e.id+'_'+date+'_'+time.replaceAll(':','')+(direction?'_'+direction:'');updates[key]={kind:'punch',employee:e.id,date,time,source:'CSV',...(direction?{direction}:{})};}if(Object.keys(updates).length)await commit(updates);return {added:Object.keys(updates).length,skipped};}
function resetPage(key){state.pages[key]=1}
async function action(node){const name=node.dataset.action,id=node.dataset.id;switch(name){case'dialog-close':closeDialog();break;case'employee-delete-selected':deleteEmployeesDialog(state.employeeSelected);break;case'employee-cleanup':deleteEmployeesDialog(duplicateSadarEmployees().map(e=>e.id),true);break;case'employee-select-page':{const list=filteredEmployees(),size=state.sizes.employees||25,page=state.pages.employees||1;const ids=list.slice((page-1)*size,page*size).map(e=>e.id),all=ids.every(id=>state.employeeSelected.includes(id));state.employeeSelected=all?state.employeeSelected.filter(id=>!ids.includes(id)):[...new Set([...state.employeeSelected,...ids])];render();break;}case'employee-import-device':deviceImportDialog(id);break;case'employee-new':employeeDialog();break;case'employee-edit':employeeDialog(id);break;case'employee-delete':deleteEmployeeDialog(id);break;case'employee-from-device':{const user=records('deviceUser').find(u=>u.id===id),device=devices().find(d=>d.id===user?.device);if(!user)throw Error('Device user record is unavailable.');if(employees().some(e=>String(e.code)===String(user.code)))throw Error('This device user is already mapped to an employee.');closeDialog();employeeDialog(undefined,{employeeId:String(user.code),code:String(user.code),name:user.name||'',branch:device?.location||''});break;}case'device-new':deviceDialog();break;case'device-edit':deviceDialog(id);break;case'device-setup':setupDialog(id);break;case'device-push':pushDialog(id);break;case'manual-new':manualDialog();break;case'leave-new':leaveDialog();break;case'open-report':state.page='reports';state.reportMode='daily';state.reportDate=C.today();render();break;case'open-devices':state.page='devices';render();break;case'receiver-configure':receiverConfigureDialog();break;case'open-settings':state.page='settings';render();break;case'report-mode':state.reportMode=node.dataset.value;state.reportView=state.reportMode==='daily'?'detail':'summary';resetPage('reports');render();break;case'report-view':state.reportView=node.dataset.value;resetPage('reports');render();break;case'page':state.pages[node.dataset.key]=(state.pages[node.dataset.key]||1)+Number(node.dataset.delta);render();break;case'employee-export':exportEmployees();break;case'report-export':exportReport();break;case'report-print':printReport();break;case'leave-status':{const l=records('leave').find(l=>l.id===id);if(!l||l.status!=='Pending')throw Error('This request has already been processed.');node.disabled=true;try{await saveRecord('leave',{...l,status:node.dataset.status},id);notify('Leave request updated.')}finally{node.disabled=false}break}case'holiday-new':openDialog('Add holiday','<form data-form="holiday" class="form-grid">'+input('Date','date',C.today(),'date',true)+input('Holiday name','name','','text',true)+actions('Save holiday')+'</form>');break;case'select-users':{const checks=$('dialog-body').querySelectorAll('input[name=employees]'),all=[...checks].every(c=>c.checked);checks.forEach(c=>c.checked=!all);node.textContent=all?'Select all':'Clear selection';break}case'device-users':node.disabled=true;try{await queueOperation(id,'inspect_users');notify('Device user download queued. Check Sync activity for confirmation.')}finally{node.disabled=false}break;case'device-sync':node.disabled=true;try{await queueOperation(id,'pull_attendance');notify('Attendance download queued. Completion waits for the device response.')}finally{node.disabled=false}break;case'copy-setup':{const d=devices().find(d=>d.id===id);await navigator.clipboard.writeText(d.accessType==='ADMS'?'Server: '+(d.serverHost||rules().receiverHost||'')+'\nPort: '+(d.serverPort||443)+'\nHTTPS: '+(d.transport==='HTTP'?'Off':'On')+'\nSerial: '+d.serial:'Device ID: '+d.id+'\nIP: '+d.address+'\nPort: '+(d.port||4370));notify('Settings copied.');break}case'connector-config':{const d=devices().find(d=>d.id===id);download('device-'+id+'.json',JSON.stringify({deviceId:id,ip:d.address,port:d.port||4370,pollSeconds:15},null,2),'application/json');break}case'import':openDialog('Import attendance','<form data-form="import" class="form-grid"><div class="notice wide">CSV: user_id,date,time,direction · YYYY-MM-DD · HH:MM · in/out. Existing punches are skipped.</div><label class="wide">Attendance CSV<input type="file" name="file" accept=".csv" required></label><div class="wide">'+button('Download template','import-template','','ghost small')+'</div>'+actions('Import records')+'</form>');break;case'import-template':download('attendance-template.csv','user_id,date,time,direction\r\n101,'+C.today()+',08:30,in\r\n101,'+C.today()+',21:00,out');break;}}
document.addEventListener('click',event=>{const nav=event.target.closest('[data-nav]');if(nav){event.preventDefault();state.page=nav.dataset.nav;render();return}const n=event.target.closest('[data-action]');if(n&&!n.disabled)Promise.resolve(action(n)).catch(e=>notify(e.message,true))});
$('dialog-close').onclick=closeDialog;$('dialog').addEventListener('close',()=>{if(state.dirty)scheduleRender()});document.addEventListener('focusout',()=>setTimeout(()=>{if(state.dirty&&canDraw())render()},50));
const bindings={'overview-date':['overviewDate','overview'],'overview-branch':['overviewBranch','overview'],'employee-search':['employeeSearch','employees'],'employee-branch':['employeeBranch','employees'],'employee-status':['employeeStatus','employees'],'report-search':['reportSearch','reports'],'report-branch':['reportBranch','reports'],'report-employee':['reportEmployee','reports'],'report-status':['reportStatus','reports'],'report-date':['reportDate','reports'],'report-month':['reportMonth','reports'],'report-from':['from','reports'],'report-to':['to','reports'],'device-search':['deviceSearch','devices'],'activity-status':['activityStatus','activity']};
function changeFilter(target){const binding=bindings[target.id];if(!binding)return;const focus=target.type==='search',pos=target.selectionStart;state[binding[0]]=target.value;resetPage(binding[1]);render();if(focus){const current=$(target.id);current?.focus();current?.setSelectionRange(pos,pos)}}
document.addEventListener('input',e=>{if(e.target.type==='search'&&bindings[e.target.id])changeFilter(e.target)});document.addEventListener('change',e=>{if(e.target.type!=='search'&&bindings[e.target.id])changeFilter(e.target);if(e.target.dataset.size){state.sizes[e.target.dataset.size]=Number(e.target.value);resetPage(e.target.dataset.size);render()}if(e.target.name==='accessType')updateDeviceFields();if(e.target.name==='transport'){const f=e.target.form;if(f&&['80','443',''].includes(f.elements.serverPort.value))f.elements.serverPort.value=e.target.value==='HTTP'?'80':'443'}});
document.addEventListener('submit',async event=>{const f=event.target.closest('[data-form]');if(!f)return;event.preventDefault();if(f.dataset.busy)return;const b=f.querySelector('button[type=submit]'),label=b.textContent;f.dataset.busy='true';b.disabled=true;b.textContent='Saving…';$('dialog-error').textContent='';try{const type=f.dataset.form,data=Object.fromEntries(new FormData(f));if(type==='employees-delete'){if(data.confirmation!=='DELETE')throw Error('Type DELETE to confirm.');await removeEmployees(data.ids.split(','),data.removeDevice==='yes');}else if(type==='receiver'){await saveReceiver(data);notify('ADMS receiver saved.')}else if(type==='employee-delete'){await deleteEmployee(f.dataset.id);}else if(type==='device-employees'){const result=await importDeviceEmployees(data);state.page='employees';state.employeeSearch='';state.employeeBranch='';state.employeeStatus='active';resetPage('employees');notify(result.added+' employees imported; '+result.skipped+' existing users skipped.')}else if(type==='push'){await queueOperation(f.dataset.device,'upsert_user',new FormData(f).getAll('employees'));notify('User push queued. Synced is shown only after device confirmation.')}else if(type==='import'){const result=await importAttendance(f.elements.file.files[0]);notify(result.added+' punches imported; '+result.skipped+' duplicates skipped.')}else{await saveRecord(type,data,f.dataset.id||undefined);notify(type==='settings'?'Settings saved.':'Record saved successfully.')}if($('dialog').open)closeDialog();state.dirty=true;scheduleRender();}catch(e){if($('dialog').open)$('dialog-error').textContent=e.message;else notify(e.message,true)}finally{delete f.dataset.busy;b.disabled=false;b.textContent=label}});
function withTimeout(promise,ms,message){let t;return Promise.race([Promise.resolve(promise),new Promise((_,reject)=>{t=setTimeout(()=>reject(Error(message)),ms)})]).finally(()=>clearTimeout(t))}
